declare(strict_types=1);require_once __DIR__.'/../src/Services/ProductFiscalData.php';require_once __DIR__.'/../src/Services/ProductFiscalCompleteness.php';use MiniErp\Services\ProductFiscalData;use MiniErp\Services\ProductFiscalCompleteness;function pf(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}$d=(new ProductFiscalData(['ncm'=>'1234.56.78','cest'=>'12.345.67','merchandise_origin'=>'0','unidade'=>'CX','taxable_unit'=>'UN','conversion_factor'=>'12','gtin'=>'7891234567895','gtin_tributable'=>'SEM GTIN','extipi'=>'01','tax_benefit_code'=>'PR123','fci_number'=>'ABC','cfop_padrao'=>'5102','cost_price'=>'2,50','minimum_stock'=>'3']))->toArray();pf($d['ncm']==='12345678'&&$d['cest']==='1234567','classification normalization');pf($d['conversion_factor']===12.0&&$d['cost_price']===2.5,'numbers');$c=(new ProductFiscalCompleteness())->evaluate($d);pf($c['complete'],'complete product');$i=(new ProductFiscalCompleteness())->evaluate([]);pf(!$i['complete']&&in_array('NCM',$i['missing'],true),'incomplete commercial product');foreach([['ncm'=>'123'],['cest'=>'1'],['merchandise_origin'=>'9'],['gtin'=>'123'],['conversion_factor'=>'0']] as $bad){try{new ProductFiscalData($bad);throw new RuntimeException('invalid accepted');}catch(InvalidArgumentException $e){}}echo "ProductFiscalData OK\n";
